    rows: Sequence[tuple[int, list[str]]],
    filters: Sequence[tuple[str, str]],
    indexes: dict[str, int],
) -> list[tuple[int, list[str]]]:
    return [
        (record_number, row)
        for record_number, row in rows
        if all(row[indexes[column]] == value for column, value in filters)
    ]


